<template><section class="page"><div class="head"><div><p>REALTIME OPERATIONS</p><h1>リアルタイム監視</h1><small>最終メッセージ：{{ lastMessageAt ? time(lastMessageAt) : '—' }}</small></div><div><span :class="['status',status]">● {{status}}</span><el-button size="small" @click="connect">再接続</el-button><el-button size="small" @click="setPaused(!paused)">{{paused?'再開':'一時停止'}}</el-button><el-button size="small" @click="clearActivities">クリア</el-button></div></div><div v-if="status!=='connected'" class="offline">ネットワーク接続が切断されています。自動再接続を試行中です。</div><div class="metrics"><article>今日の売上高<strong>{{money(metrics?.totalRevenue??0)}}</strong></article><article>今日の注文数<strong>{{metrics?.totalOrders??0}}</strong></article><article>オンライン人数<strong>{{onlineCount}}</strong></article><article>平均注文金額<strong>{{money(avg)}}</strong></article></div><div class="grid"><article class="surface"><h2>直近60秒の売上高</h2><svg viewBox="0 0 500 160"><polyline :points="revenuePoints"/></svg></article><article class="surface"><h2>直近60秒の注文数</h2><svg viewBox="0 0 500 160"><polyline class="orders" :points="orderPoints"/></svg></article></div><div class="grid"><article class="surface"><h2>リアルタイム注文</h2><transition-group name="new" tag="div"><div v-for="o in recentOrders" :key="o.orderNumber" class="row"><span>{{o.orderNumber}}</span><small>{{o.region}} · {{time(o.createdAt)}}</small><b>{{money(o.totalAmount)}}</b></div></transition-group><div v-if="!recentOrders.length" class="empty">注文を待機中です</div></article><article class="surface"><h2>最近の動的イベント</h2><div v-for="a in activities" :key="a.id" class="row"><span>{{a.message}}</span><small>{{time(a.timestamp)}}</small></div><div v-if="!activities.length" class="empty">イベントを待機中です</div></article></div></section></template>
<script setup lang="ts">import dayjs from'dayjs';import{computed}from'vue';import{useWebSocket}from'../composables/useWebSocket';const{status,onlineCount,metrics,recentOrders,activities,samples,paused,lastMessageAt,connect,setPaused,clearActivities}=useWebSocket();const money=(x:number)=>new Intl.NumberFormat('ja-JP',{style:'currency',currency:'JPY',maximumFractionDigits:0}).format(x);const time=(x:string)=>dayjs(x).format('HH:mm:ss');const avg=computed(()=>metrics.value?.totalOrders?metrics.value.totalRevenue/metrics.value.totalOrders:0);function points(key:'revenue'|'orders'){const v=samples.value.map(x=>x[key]),max=Math.max(...v,1),n=Math.max(v.length-1,1);return v.map((x,i)=>`${i/n*480+10},${150-x/max*130}`).join(' ')}const revenuePoints=computed(()=>points('revenue'));const orderPoints=computed(()=>points('orders'))</script>
<style scoped>.page{padding-top:22px}.head{display:flex;justify-content:space-between;align-items:start;margin:22px 0}.head p{color:#4bc9f7;font-size:11px;letter-spacing:.14em}.head h1{margin:8px 0;color:#eff8ff}.head small{color:#7f9bb5}.status{margin-right:8px;color:#ffbf6b}.status.connected{color:#49d6a2}.offline{margin-bottom:14px;padding:10px;border-radius:8px;color:#ffbf6b;background:#453420;font-size:12px}.metrics,.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.grid{grid-template-columns:1fr 1fr;margin-top:16px}.metrics article,.surface{padding:20px;border:1px solid rgba(125,181,230,.13);border-radius:13px;background:#10243d;color:#91abc1}.metrics strong{display:block;margin-top:10px;color:#eff8ff;font-size:24px}.surface h2{margin:0 0 12px;color:#eaf4fc;font-size:15px}.surface svg{width:100%;height:160px}.surface polyline{fill:none;stroke:#55cdf8;stroke-width:3}.surface polyline.orders{stroke:#817cff}.row{display:flex;gap:10px;padding:10px 0;border-bottom:1px solid rgba(126,174,218,.1);color:#c8ddeb;font-size:12px}.row small{color:#7f9bb5}.row b{margin-left:auto}.empty{padding:35px;color:#7894ad;text-align:center}.new-enter-active{transition:all .25s ease}.new-enter-from{opacity:0;transform:translateY(-8px)}@media(max-width:800px){.head{flex-direction:column;gap:12px}.metrics,.grid{grid-template-columns:1fr}}</style>
